  border-color: rgba(var(--accent-rgb), 0.12);
}

.dashboard-nav__item.is-active {
  border-radius: 18px;
  background: transparent;
  color: var(--accent);
  border-color: transparent;
  box-shadow: none;
}

.dashboard-nav__item.is-active:hover,
.dashboard-nav__item.is-active:focus-visible {
