.order-insight-shell .insight-main-grid {
  --order-insight-invoice-width: 390px;
  align-items: start;
  grid-template-columns:
    minmax(520px, 600px)
    minmax(460px, 1fr)
    minmax(320px, var(--order-insight-invoice-width));
  min-height: 0 !important;
}

html.order-insight-page-root,
body.order-insight-page {
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

body.order-insight-page {
  --order-insight-body-right-gutter: 37px;
  --order-insight-scrollbar-gutter: 17px;
  box-sizing: border-box;
  padding-right: var(--order-insight-body-right-gutter);
}

html.order-insight-page-root::-webkit-scrollbar,
body.order-insight-page::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

body.order-insight-page .order-insight-shell.page-shell {
  width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  height: 100vh !important;
  min-height: 100vh !important;
  padding-top: 10px !important;
  padding-right: 0 !important;
  padding-bottom: 0 !important;
  box-sizing: border-box;
  overflow: hidden !important;
}

body.order-insight-page .dashboard-layout,
body.order-insight-page .dashboard-content,
body.order-insight-page .insight-main-grid {
  height: 100% !important;
  min-height: 0 !important;
}

body.order-insight-page .dashboard-content {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) !important;
  box-sizing: border-box;
  padding-right: var(--order-insight-scrollbar-gutter);
}

.order-insight-scroll-proxy {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 260;
  width: var(--order-insight-scrollbar-gutter, 17px);
  overflow-x: hidden;
  overflow-y: auto;
  background: transparent;
}

.order-insight-scroll-proxy[hidden] {
  display: none !important;
}

.order-insight-scroll-proxy__spacer {
  width: 1px;
  min-height: 100%;
}

.order-insight-shell .insight-main-grid > .dashboard-panel:first-child {
  --insight-order-panel-padding: 0px;
  position: relative;
  z-index: 0;
  align-self: stretch;
  height: calc(100vh - 92px) !important;
  min-height: 0 !important;
  max-width: 600px;
  width: 100%;
  display: grid;
  grid-template-rows: auto 18px minmax(0, 1fr);
  gap: 0;
  align-content: stretch;
  overflow: visible;
  transition: grid-template-rows 180ms ease;
}

.order-insight-shell
  .insight-main-grid
  > .insight-order-list-shell.dashboard-panel.is-order-list-scrolled {
  grid-template-rows: auto 0px minmax(0, 1fr);
}

.order-insight-shell .insight-main-grid > .dashboard-panel:first-child > .insight-order-controls-panel {
  position: relative;
  z-index: 520;
}

.order-insight-shell .insight-tracking-panel {
  max-width: none;
  width: 100%;
  justify-self: start;
}

.order-insight-shell .insight-order-detail-panel {
  --insight-order-detail-panel-padding: 22px;
  --insight-order-detail-scroll-height: calc(100vh - 236px);
  min-width: 0;
  max-width: var(--order-insight-invoice-width, 390px);
  width: 100%;
  justify-self: end;
  align-self: start;
  min-height: 0 !important;
  overflow: visible;
}

.order-insight-shell .insight-order-detail-panel .insight-side-tabs {
  margin-bottom: 14px;
}

.order-insight-shell .insight-order-detail-panel .insight-side-panel-stack {
  min-height: 0;
  height: auto;
  max-height: var(--insight-order-detail-scroll-height);
  overflow: hidden;
}

@media (max-width: 1360px) {
  .order-insight-shell .insight-main-grid {
    grid-template-columns: minmax(520px, 600px) minmax(0, 1fr);
  }

  .order-insight-shell .insight-order-detail-panel {
    grid-column: 1 / -1;
    max-width: var(--order-insight-invoice-width, 390px);
    justify-self: end;
  }
}

@media (max-width: 860px) {
  .order-insight-shell .insight-main-grid {
    grid-template-columns: 1fr;
  }

  .order-insight-shell .insight-main-grid > .dashboard-panel:first-child {
    min-height: auto;
    max-width: none;
  }

  .order-insight-shell .insight-order-detail-panel {
    grid-column: auto;
    max-width: none;
    justify-self: stretch;
  }
}

.dashboard-shell--panel-nav .insight-main-grid .panel,
.dashboard-shell--panel-nav .insight-main-grid .dashboard-panel {
  box-shadow: none !important;
  backdrop-filter: none !important;
