.insight-order-tracking__step.is-complete:not(:last-child)::after {
  display: none;
}

.insight-order-tracking__connector {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  height: 10px;
  margin: 0 10px;
  border-radius: 999px;
  border: 0;
  background: #e5e7eb;
  overflow: hidden;
}

.insight-order-tracking__connector.is-complete {
