.insight-order-tracking__connector::after {
  content: "";
  position: absolute;
  inset: 0;
  width: 42%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    rgba(var(--accent-rgb), 0) 0%,
    rgba(var(--accent-rgb), 0.42) 42%,
    rgb(var(--accent-rgb)) 100%
  );
  transform: translateX(-120%);
  opacity: 0;
}

.insight-order-tracking__connector.is-active::after {
  opacity: 1;
  animation: insightTrackingConnectorFlow 1500ms ease-in-out infinite;
}

.insight-order-tracking__connector.is-complete::after {
  width: 100%;
  background: rgb(var(--accent-rgb));
  transform: translateX(0);
  opacity: 1;
  animation: none;
}

@keyframes insightTrackingConnectorFlow {
  0% {
    transform: translateX(-120%);
