  grid-template-rows: 0fr;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-5px);
  transition: grid-template-rows 220ms ease, opacity 180ms ease, transform 220ms ease;
}

.packing-addons-dropdown.is-open {
  grid-template-rows: 1fr;
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.packing-addons-dropdown__inner {
  position: relative;
  display: grid;
  gap: 10px;
  min-height: 0;
  overflow: hidden;
  padding-top: 6px;
  padding-left: 34px;
  padding-right: 30px;
  padding-bottom: 6px;
}

.packing-addons-dropdown__inner::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 6px;
  bottom: 23px;
  width: 2px;
  border-radius: 999px;
  background: rgba(var(--accent-rgb), 0.58);
}

.packing-dashboard-page .insight-order-item--addon {
  position: relative;
  padding-block: 12px;
  border-style: dashed;
  border-color: rgba(var(--accent-rgb), 0.38);
  background: rgba(255, 255, 255, 0.52);
  box-sizing: border-box;
}

.packing-dashboard-page .insight-order-item--addon.insight-order-item--scan-complete {
  border-style: solid;
}

.packing-dashboard-page .insight-order-item--addon::before {
  content: "";
  position: absolute;
  left: -18px;
  top: 50%;
  width: 18px;
  height: 2px;
  border-radius: 999px;
  background: rgba(var(--accent-rgb), 0.58);
}

.packing-dashboard-page .insight-order-item--addon .insight-order-item__amount {
  color: #059669;
  font-weight: 700;
}

.packing-addon-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  min-width: 30px;
  height: 30px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--text-primary);
  line-height: 1;
  transition: background-color 180ms ease, border-color 180ms ease, color 180ms ease;
}

.packing-addon-toggle:hover,
.packing-addon-toggle:focus-visible,
.packing-addon-toggle.is-open {
  border-color: transparent;
  background: transparent;
  color: var(--accent);
}

.packing-addon-toggle__chevron {
  font-size: 11px;
  transition: transform 200ms ease;
}

.packing-addon-toggle.is-open .packing-addon-toggle__chevron {
  transform: rotate(180deg);
}

@media (max-width: 640px) {
  .packing-addons-dropdown__inner {
    padding-left: 22px;
    padding-right: 10px;
  }

  .packing-addons-dropdown__inner::before {
    left: 10px;
  }

  .packing-dashboard-page .insight-order-item--addon::before {
    left: -12px;
    width: 12px;
  }
}

.insight-order-item--clickable {
  cursor: pointer;
  border-color: rgba(var(--accent-rgb), 0.18);
  transition: background-color 150ms ease, border-color 150ms ease, transform 150ms ease;
}

.insight-order-item--clickable:hover,
.insight-order-item--clickable:focus-visible {
  background: rgba(255, 255, 255, 0.92);
  transform: translateY(-1px);
}

.insight-order-item--selected {
  outline: none;
  border-color: rgba(var(--accent-rgb), 0.72);
  box-shadow: inset 0 0 0 2px rgba(var(--accent-rgb), 0.88);
}

.packing-dashboard-page .insight-order-item--addon.insight-order-item--selected {
  border-style: solid;
}

.insight-order-item--scan-complete,
.insight-order-item--scan-complete.insight-order-item--selected {
  border-color: rgba(47, 125, 79, 0.72);
  outline: none;
  box-shadow: inset 0 0 0 2px rgba(5, 150, 105, 0.64);
}

.insight-order-item--scan-complete.insight-order-item--selected {
  border-color: rgba(var(--accent-rgb), 0.72);
  box-shadow: inset 0 0 0 2px rgba(var(--accent-rgb), 0.88);
}


.insight-order-item--scan-required:hover,
.insight-order-item--scan-required:focus-visible {
  transform: none;
}

.barcode-hidden-input {
