.insight-order-item__copy {
  display: grid;
  gap: 4px;
}

.insight-order-item__heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.insight-order-item__photo-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  min-width: 28px;
  height: 28px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  line-height: 1;
  box-shadow: none;
  transition: color 160ms ease;
}

.insight-order-item__photo-btn i,
.insight-order-item__photo-btn svg {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  font-size: 16px;
  line-height: 1;
  transform-origin: center;
  transition: background-color 160ms ease, color 160ms ease, transform 160ms ease;
}

.insight-order-item__photo-btn svg {
  flex: 0 0 22px;
  fill: currentColor;
  stroke: none;
}

.insight-order-item__photo-icon path {
  fill: currentColor !important;
  stroke: none !important;
}

.insight-order-item__photo-btn:hover,
.insight-order-item__photo-btn:focus-visible {
  background: transparent;
  border-color: transparent;
  color: var(--accent);
  outline: none;
}

.insight-order-item__photo-btn:hover i,
.insight-order-item__photo-btn:focus-visible i,
.insight-order-item__photo-btn:hover svg,
.insight-order-item__photo-btn:focus-visible svg {
  background: transparent;
  transform: scale(1.16);
}

.insight-order-detail__item-photo-btn:disabled:hover i,
.insight-order-detail__item-photo-btn:disabled:focus-visible i,
.insight-order-detail__item-photo-btn:disabled:hover svg,
.insight-order-detail__item-photo-btn:disabled:focus-visible svg {
  background: transparent;
  transform: none;
}

.scan-status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 22px;
  padding: 0 6px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  vertical-align: middle;
  overflow: visible;
}

.scan-status-badge--pending {
  color: #dc2626;
  font-weight: 500;
}

.scan-status-badge--complete {
  color: #22c55e;
  width: 26px;
  min-width: 26px;
  height: 20px;
  padding: 0;
  border-radius: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.scan-status-badge__check {
  width: 28px;
  height: 30px;
  display: block;
  flex: 0 0 auto;
  overflow: visible;
  opacity: 0;
  transform: translateY(-2px) scale(0.72);
  animation: scan-complete-check-pop 800ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.scan-status-badge__check path {
  fill: none;
  stroke: #059669;
  stroke-width: 66;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.scan-status-badge__check-path {
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: scan-complete-check-draw 800ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes scan-complete-check-pop {
  to {
    opacity: 1;
    transform: translateY(-2px) scale(1);
  }
}

@keyframes scan-complete-check-draw {
  to {
    stroke-dashoffset: 0;
  }
}

.packing-order-transfer {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 10040;
  width: 74px;
  height: 74px;
  pointer-events: none;
  filter: drop-shadow(0 18px 30px rgba(var(--accent-rgb), 0.26));
  will-change: transform, opacity;
}

.packing-order-card-animation-overlay {
  position: absolute;
  inset: 0;
  z-index: 8;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: inherit;
  background: transparent;
  pointer-events: none;
  opacity: 0;
  animation: packing-order-card-overlay-in 180ms ease forwards;
}

.packing-order-card-animation-overlay.is-leaving {
  animation: packing-order-card-overlay-out 220ms ease forwards;
}

.packing-order-card-animation-overlay .packing-order-transfer {
  position: relative;
  top: auto;
  left: auto;
  width: 156px;
  height: 156px;
  filter: drop-shadow(0 18px 30px rgba(var(--accent-rgb), 0.28));
}

.packing-order-transfer__box {
  position: relative;
  width: 74px;
  height: 74px;
  transform-origin: center;
  animation: packing-order-transfer-json var(--packing-box-duration, 3400ms) cubic-bezier(0.22, 1, 0.36, 1) both;
}

.packing-order-card-animation-overlay .packing-order-transfer__box {
  width: 156px;
  height: 156px;
  animation: packing-order-card-box-motion var(--packing-box-duration, 3400ms) cubic-bezier(0.22, 1, 0.36, 1) both;
}

.packing-order-transfer__box--lottie {
  display: grid;
  place-items: center;
  overflow: visible;
}

.packing-order-transfer__box--player {
  display: grid;
  place-items: center;
  overflow: visible;
}

.packing-order-transfer__lottie-player {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.packing-order-transfer__lottie-player svg {
  display: block;
  width: 100% !important;
  height: 100% !important;
  overflow: visible !important;
}

.packing-order-transfer__lottie {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.packing-order-card-animation-overlay .packing-order-transfer__lottie {
  animation: packing-order-card-lottie-sway 940ms ease-in-out infinite;
}

.packing-order-transfer__lottie-frame {
  opacity: 0;
  transition: opacity 120ms linear;
}

.packing-order-transfer__lottie-frame.is-active {
  opacity: 1;
}

.packing-order-transfer__lottie-path {
  opacity: 0;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: packing-order-lottie-path-draw var(--lottie-path-duration, 720ms) cubic-bezier(0.22, 1, 0.36, 1) var(--lottie-path-delay, 0ms) forwards;
}

.packing-order-transfer__lottie-path.is-visible-at-start {
  opacity: 1;
  stroke-dashoffset: 0;
  animation: none;
}

.is-packing-transfer-source {
  position: relative;
  overflow: hidden;
}

.insight-order-card.is-packing-transfer-source {
  opacity: 1;
  transform: none;
  transition: opacity 180ms ease, transform 180ms ease;
}

.is-packing-transfer-source > :not(.packing-order-card-animation-overlay) {
  filter: blur(2px);
  opacity: 0.68;
  transition: filter 180ms ease, opacity 180ms ease;
}

.packing-card-flight-clone {
  position: fixed !important;
  z-index: 10045;
  margin: 0 !important;
  pointer-events: none;
  transform-origin: top left;
  will-change: transform, opacity;
  filter: drop-shadow(0 26px 44px rgba(var(--accent-rgb), 0.24));
}

.is-packing-card-flight-source {
  opacity: 0.24;
  transform: scale(0.985);
  transition: opacity 180ms ease, transform 180ms ease;
}

@keyframes packing-order-card-overlay-in {
  to {
    opacity: 1;
  }
}

@keyframes packing-order-card-overlay-out {
  to {
    opacity: 0;
  }
}

@keyframes packing-order-transfer-json {
  0% {
    opacity: 0;
    transform: translateY(0) scale(0.92) rotate(-3deg);
  }
  8% {
    opacity: 1;
    transform: translateY(-4px) scale(1) rotate(0deg);
  }
  22% {
    transform: translateY(-9px) scale(1.04) rotate(3deg);
  }
  45% {
    transform: translateY(0) scale(0.98) rotate(-2deg);
  }
  72% {
    transform: translateY(-7px) scale(1.03) rotate(2deg);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1) rotate(0deg);
  }
}

@keyframes packing-order-card-box-motion {
  0% {
    opacity: 0;
    transform: translateY(10px) scale(0.72) rotate(-5deg);
  }
  10% {
    opacity: 1;
    transform: translateY(0) scale(1) rotate(0deg);
  }
  24% {
    transform: translateY(-12px) scale(1.06) rotate(4deg);
  }
  38% {
    transform: translateY(4px) scale(0.98) rotate(-4deg);
  }
  54% {
    transform: translateY(-8px) scale(1.04) rotate(3deg);
  }
  70% {
    transform: translateY(3px) scale(1) rotate(-2deg);
  }
  86% {
    transform: translateY(-5px) scale(1.03) rotate(2deg);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1) rotate(0deg);
  }
}

@keyframes packing-order-card-lottie-sway {
  0%,
  100% {
    transform: translateY(0) rotate(-1deg);
  }
  50% {
    transform: translateY(-6px) rotate(1.5deg);
  }
}

@keyframes packing-order-lottie-path-draw {
  to {
    opacity: 1;
    stroke-dashoffset: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .packing-order-transfer__box {
    animation-duration: 240ms;
  }
}

