.packing-modal__btn {
  flex: 1;
  padding: 12px 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease;
}

.packing-modal__btn:active {
  transform: scale(0.98);
}

.packing-modal__btn--secondary {
  background: #d1d5db;
  border: 2px solid transparent;
  color: var(--text-primary);
  box-shadow: none;
}

.packing-modal__btn--secondary:hover {
  background: #4b5563;
  border-color: transparent;
  color: #ffffff;
  box-shadow: none;
}

.packing-modal__btn--primary {
  background: var(--accent);
  border: 2px solid var(--accent);
  color: var(--accent-contrast);
}

.packing-modal__btn--primary:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.insight-order-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 16px;
}

.insight-order-meta-note {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.45;
}

.product-insight-main-grid {
  align-items: stretch;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.product-insight-main-grid > .dashboard-panel,
.product-insight-side-stack > .dashboard-panel {
  min-height: 700px;
}

.product-insight-main-grid > .product-insight-sold-list-shell.dashboard-panel {
  display: grid;
  grid-template-rows: auto 0 minmax(0, 1fr);
  gap: 0;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  overflow: visible;
  transition: grid-template-rows 180ms ease;
}

.product-insight-main-grid > .product-insight-sold-list-shell.is-product-list-scrolled {
  grid-template-rows: auto 0 minmax(0, 1fr);
}

.product-insight-shell .product-insight-sold-controls-panel.dashboard-panel {
  margin-bottom: 0;
  border-bottom: 1.5px solid rgba(15, 23, 42, 0.14) !important;
  box-shadow: 0 10px 14px -14px rgba(15, 23, 42, 0.55) !important;
}

.product-insight-shell .product-insight-sold-controls-panel .product-insight-tools {
  margin-bottom: 0;
}

.product-insight-shell .product-insight-sold-controls-spacer {
  position: relative;
  z-index: 0;
  height: 0;
  min-height: 0;
  background: transparent !important;
  pointer-events: none;
  opacity: 0;
  transform: translateY(0);
  transition:
    height 180ms ease,
    min-height 180ms ease,
    opacity 160ms ease,
    transform 180ms ease;
}

.product-insight-shell
  .product-insight-sold-list-shell.is-product-list-scrolled
  .product-insight-sold-controls-spacer {
  height: 0;
  min-height: 0;
  opacity: 0;
  transform: translateY(-18px);
}

.product-insight-shell .product-insight-sold-rank-list {
  box-sizing: border-box;
  align-content: start;
  grid-auto-rows: max-content;
  min-height: 0;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 22px 22px 22px;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: rgba(var(--accent-rgb), 0.78) transparent;
}

.product-insight-shell .product-insight-sold-rank-list::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.product-insight-shell .product-insight-sold-rank-list::-webkit-scrollbar-track {
  background: transparent;
}

.product-insight-shell .product-insight-sold-rank-list::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgba(var(--accent-rgb), 0.78);
  background-clip: content-box;
}

.product-insight-shell .product-insight-sold-rank-list::-webkit-scrollbar-thumb:hover {
  background: rgba(var(--accent-rgb), 0.94);
  background-clip: content-box;
}

.product-insight-side-stack {
  display: grid;
  align-self: start;
  gap: 18px;
}

body.product-insight-page .product-insight-side-stack,
body.product-insight-page .product-insight-side-stack > .dashboard-panel {
  height: auto !important;
  min-height: 0 !important;
  align-self: start;
}

@media (max-width: 860px) {
  .product-insight-main-grid > .dashboard-panel,
  .product-insight-side-stack > .dashboard-panel {
    min-height: auto;
  }
}

.product-insight-side-detail {
  display: grid;
  gap: 16px;
  padding-bottom: 10px;
}

.product-insight-side-summary,
.product-insight-review-summary {
  display: grid;
  gap: 18px;
  min-height: 0;
}

.product-insight-income-chart-summary {
  display: grid;
  gap: 18px;
}

.product-insight-income-chart-summary__top {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 14px;
  flex-wrap: wrap;
}

.product-insight-income-chart-summary__controls {
  width: 100%;
}

.product-insight-income-chart-summary__context {
  display: inline-flex;
  align-items: center;
  min-height: 42px;
  padding: 0 12px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.05);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}

.product-insight-income-chart-summary__overview {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding: 0;
  border-radius: 12px;
  border: none;
  background: transparent;
  box-shadow: none;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.product-insight-income-chart-summary__overview.is-up {
  background: transparent;
  border-color: transparent;
}

.product-insight-income-chart-summary__overview.is-down {
  background: transparent;
  border-color: transparent;
}

.product-insight-income-chart-summary__overview.is-flat {
  background: transparent;
  border-color: transparent;
}

.product-insight-income-chart-summary__overview-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
}

.product-insight-income-chart-summary__overview-label {
  display: block;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.product-insight-income-chart-summary__overview-main {
  display: inline-flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: nowrap;
}

.product-insight-income-chart-summary__controls .product-insight-income-chart-summary__overview {
  margin-left: auto;
}

.product-insight-income-chart-summary__overview-value {
  color: var(--text-primary);
  font-size: 22px;
  font-weight: 800;
  line-height: 1;
}

.product-insight-income-chart-summary__overview-change {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.01em;
}

.product-insight-income-chart-summary__overview-change.is-up {
  background: rgba(34, 197, 94, 0.12);
  color: rgb(21, 128, 61);
}

.product-insight-income-chart-summary__overview-change.is-down {
  background: rgba(239, 68, 68, 0.12);
  color: rgb(185, 28, 28);
}

.product-insight-income-chart-summary__overview-change.is-flat {
  background: rgba(148, 163, 184, 0.14);
  color: rgb(71, 85, 105);
}

.product-insight-income-chart-summary__chart {
