  gap: 14px;
}

.product-insight-income-chart-summary__chart .product-insight-rank-card__back-chart-axis {
  min-height: 180px;
  min-width: 96px;
  padding-bottom: 12px;
}

.product-insight-income-chart-summary__chart .product-insight-rank-card__back-chart-axis-label {
  font-size: 11px;
}

.product-insight-income-chart-summary__chart .product-insight-rank-card__back-chart-footer {
  min-height: 22px;
}

.product-insight-income-chart-summary__chart .product-insight-rank-card__back-chart-footer-shell {
  grid-template-columns: minmax(0, 1fr) minmax(96px, auto);
  gap: 14px;
}

.product-insight-income-chart-summary__chart .product-insight-rank-card__back-chart-stat {
  padding-top: 6px;
}

.product-insight-income-chart-summary__chart .product-insight-rank-card__back-chart-stat-label {
  font-size: 11px;
}

.product-insight-review-summary__controls {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.product-insight-review-summary__dropdown {
  position: relative;
  min-width: 150px;
}

.product-insight-review-summary__dropdown .product-category-multiselect__trigger {
  min-height: 42px;
  padding: 10px 14px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  background: #ffffff;
  font-size: 13px;
  font-weight: 600;
}

.product-insight-review-summary__dropdown .product-category-multiselect__trigger:hover,
.product-insight-review-summary__dropdown .product-category-multiselect__trigger:active,
.product-insight-review-summary__dropdown .product-category-multiselect__trigger:focus-visible {
  background: #ffffff;
  box-shadow: none;
}

.product-insight-review-summary__dropdown:focus-within .product-category-multiselect__trigger {
  box-shadow:
    0 0 0 1px rgba(15, 23, 42, 0.16),
    0 0 0 4px rgba(15, 23, 42, 0.06);
  outline: none;
}

.product-insight-review-summary__dropdown .product-category-multiselect__summary {
  font-size: 13px;
  font-weight: 600;
}

.product-insight-review-summary__dropdown.is-open .product-panel-grid__inventory-category-filter-icon {
