}

.product-insight-review-summary__menu {
  max-height: 220px;
}

.product-insight-review-summary__dropdown[data-review-dropdown="rating"] .product-insight-review-summary__menu {
  max-height: none;
  overflow-y: hidden;
}

.product-insight-review-summary__dropdown[data-sold-dropdown="range"] .product-insight-review-summary__menu {
  max-height: none;
  overflow-y: hidden;
}

.product-insight-review-summary__menu .product-category-multiselect__option {
  width: 100%;
  border: 0;
  background: #ffffff;
  justify-content: flex-start;
  text-align: left;
}

.product-insight-review-summary__menu .product-category-multiselect__option:hover,
.product-insight-review-summary__menu .product-category-multiselect__option:focus-visible,
.product-insight-review-summary__menu .product-category-multiselect__option:active {
  background: #f3f4f6;
  color: var(--text-primary);
  transform: none;
  box-shadow: none;
}

.product-insight-review-summary__menu .product-category-multiselect__option.is-selected {
  background: rgba(var(--accent-rgb), 0.1);
  color: var(--accent-text);
}

.product-insight-side-summary__header,
.product-insight-review-summary__product {
  display: flex;
  align-items: center;
  gap: 14px;
}

.product-insight-side-summary__copy,
.product-insight-review-summary__product-copy {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.product-insight-side-summary__copy h3,
.product-insight-review-summary__product-copy h3 {
  margin: 0;
}

.product-insight-side-summary__copy p,
.product-insight-review-summary__product-copy p {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.5;
}

.product-insight-side-summary__metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.product-insight-review-summary__hero {
  display: grid;
  grid-template-columns: minmax(124px, 154px) minmax(0, 1fr);
  gap: 10px;
  align-items: center;
}

.product-insight-review-summary__score {
  display: grid;
  gap: 10px;
  align-content: start;
}

.product-insight-review-summary__score-value {
  font-size: clamp(56px, 7vw, 82px);
  line-height: 0.92;
  font-weight: 600;
  color: var(--text-primary);
}

.product-insight-review-summary__stars .product-insight-star {
  width: 28px;
  height: 28px;
}

.product-insight-review-summary__total {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}

.product-insight-review-breakdown {
  display: grid;
  gap: 5px;
}

.product-insight-review-breakdown__row {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto;
  gap: 20px;
  align-items: center;
}

.product-insight-review-breakdown__label {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 700;
  text-align: right;
}

.product-insight-review-breakdown__track {
  position: relative;
  height: 14px;
  border-radius: 999px;
  background: #e5e7eb;
  overflow: hidden;
}

.product-insight-review-breakdown__fill {
  display: block;
  height: 100%;
