  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
}

.product-insight-review-breakdown__count {
  min-width: 28px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
  text-align: right;
}

.product-insight-review-summary__comments-heading {
  display: grid;
  gap: 4px;
}

.product-insight-review-summary__comments-heading strong {
  font-size: 14px;
  color: var(--text-primary);
}

.product-insight-review-summary__comments-heading span {
  color: var(--text-secondary);
  font-size: 12px;
}

.product-insight-review-comments {
  display: grid;
  gap: 12px;
  align-content: start;
  grid-auto-rows: max-content;
  max-height: min(34vh, 360px);
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 2px 10px 0 2px;
  margin-right: -6px;
  scrollbar-gutter: stable;
}

.product-insight-review-comment {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 0;
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
}

.product-insight-review-comment__header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.product-insight-review-comment__person {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}

.product-insight-review-comment__body {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.product-insight-review-comment__avatar {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: linear-gradient(135deg, #d1d5db 0%, #9ca3af 100%);
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.product-insight-review-comment__identity {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.product-insight-review-comment__identity strong {
  color: var(--text-primary);
  font-size: 13px;
}

.product-insight-review-comment__identity span {
  color: var(--text-secondary);
  font-size: 12px;
}

.product-insight-review-comment__rating-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
}

.product-insight-review-comment__rating {
  display: inline-flex;
  width: fit-content;
  justify-self: start;
  align-items: center;
}

.product-insight-review-comment__date {
  flex: 0 0 auto;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.product-insight-review-comment__rating .product-insight-stars {
  gap: 4px;
}

.product-insight-review-comment__rating .product-insight-star {
  width: 28px;
  height: 28px;
  color: rgba(245, 158, 11, 0.22);
}

.product-insight-review-comment__rating .product-insight-star__outline {
  fill: currentColor;
  stroke: none;
}

.product-insight-review-comment__rating .product-insight-star__fill {
