  border-radius: 6px;
}

.product-insight-review-media {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 8px;
}

.product-insight-review-media__item {
  position: relative;
  flex: 0 0 100px;
  width: 100px;
  height: 100px;
  min-width: 0;
  aspect-ratio: auto;
  margin: 0;
  overflow: hidden;
  border-radius: 8px;
  background: #eef2f7;
  border: 1px solid rgba(148, 163, 184, 0.22);
}

.product-insight-review-media__item img,
.product-insight-review-media__item video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.product-insight-review-media__item video {
  background: #0f172a;
}

.product-insight-review-media__badge {
  position: absolute;
  left: 8px;
  bottom: 8px;
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 8px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.74);
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
}

.product-insight-review-media--modal {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.product-insight-review-media--modal .product-insight-review-media__item {
  width: auto;
  height: auto;
  flex: initial;
  aspect-ratio: 4 / 3;
}

.product-insight-review-comment__actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.product-insight-review-comment__action {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition:
    background-color 160ms ease,
    color 160ms ease,
    transform 160ms ease,
    box-shadow 160ms ease;
}

.product-insight-review-comment__action:hover {
  background: transparent;
  color: var(--accent-text);
  transform: translateY(-1px);
}

.product-insight-review-comment__action:focus-visible {
  outline: none;
  box-shadow: none;
}

.product-insight-review-comment__action.is-active {
  background: transparent;
  color: var(--accent-text);
}

.product-insight-review-comment__action-icon {
  width: 16px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.product-insight-review-comment__action-icon svg {
  width: 16px;
  height: 16px;
}

.product-insight-review-comment__action-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
