    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.stock-product-list {
  display: grid;
  gap: 22px;
  align-content: start;
  grid-auto-rows: max-content;
  isolation: isolate;
}

.stock-product-card {
  position: relative;
  display: grid;
  gap: 14px;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 8px !important;
  background: var(--surface-soft);
}

.stock-product-card__header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 48px;
}

.stock-product-card__edit-button {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 44px;
  min-width: 44px;
  min-height: 44px;
  padding: 0;
  border: none;
  border-radius: 10px;
  background: transparent;
  box-shadow: none;
  color: var(--text-secondary);
  z-index: 1;
}

.stock-product-card__edit-button:hover,
.stock-product-card__edit-button:focus-visible {
  background: transparent;
  border: none;
  box-shadow: none;
  color: var(--accent-text);
  outline: none;
}

.stock-product-card__edit-button.is-editing {
  color: var(--accent-text);
}

.stock-product-card__edit-button i,
.stock-product-card__edit-button svg {
  width: 22px;
  height: 22px;
  font-size: 22px;
  line-height: 1;
  display: block;
}

.stock-product-card__edit-button:hover i,
.stock-product-card__edit-button:focus-visible i {
  font-weight: 900;
}

.stock-product-card__edit-button:disabled,
.stock-product-card__edit-button[aria-disabled="true"] {
  opacity: 0.45;
  cursor: not-allowed;
}

.stock-product-card__variant-toggle {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 40px;
  min-width: 40px;
  min-height: 40px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  box-shadow: none;
  color: var(--text-secondary);
  z-index: 1;
}

.stock-product-card__variant-toggle:hover,
.stock-product-card__variant-toggle:focus-visible {
  background: transparent;
  box-shadow: none;
  color: var(--accent-text);
  outline: none;
}

.stock-product-card__variant-toggle-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}

.stock-product-card__variant-toggle-icon svg {
  width: 18px;
  height: 18px;
  display: block;
  transition: transform 160ms ease;
}

.stock-product-card__variant-toggle.is-open .stock-product-card__variant-toggle-icon svg {
  transform: rotate(180deg);
}

.stock-product-card__media {
  width: 72px;
  height: 72px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 8px;
  background: rgba(var(--accent-rgb), 0.08);
}

.stock-product-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 8px;
}

.stock-product-card__placeholder {
  padding: 10px;
  text-align: center;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
}

.stock-product-card__title {
  min-width: 0;
}

.stock-product-card__title h3 {
  margin: 0;
  font-weight: 500;
  font-size: 25px;
}

.stock-product-card__title p {
  margin: 6px 0 0;
  color: var(--text-secondary);
  line-height: 1.5;
}

.live-chat-stock-shell .stock-variant-section {
  display: grid;
  gap: 10px;
  padding-top: 2px;
}

.live-chat-stock-shell .stock-variant-section__title {
  margin: 0;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.live-chat-stock-shell .stock-variant-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
}

.live-chat-stock-shell .stock-variant-card {
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 18px;
  border: none;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(249, 250, 251, 0.96) 100%);
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.06), 0 2px 6px rgba(15, 23, 42, 0.04);
}

.live-chat-stock-shell .stock-variant-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.live-chat-stock-shell .stock-variant-card__title {
  min-width: 0;
  color: #0f172a;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
}

.live-chat-stock-shell .stock-variant-card__copy {
  margin: 0;
  color: #64748b;
  font-size: 11px;
  line-height: 1.45;
}

.live-chat-stock-shell .stock-variant-card__meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.live-chat-stock-shell .stock-variant-card__meta-item {
  min-width: 0;
  padding: 12px 14px;
  border: none;
  border-radius: 8px;
  background: #f3f4f6;
}

.live-chat-stock-shell .stock-variant-card__meta-label {
  display: block;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.live-chat-stock-shell .stock-variant-card__meta-value {
  display: block;
  margin-top: 4px;
  color: #0f172a;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.stock-chip-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  border-radius: 3px;
  align-items: center;
}

.stock-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: fit-content;
  padding: 8px 12px;
  border-radius: 4px;
  color: var(--accent-text);
  font-size: 12px;
  font-weight: 500;
}

.stock-chip.is-low {
  color: #9a6700;
}

.stock-chip.is-critical {
  color: #d49a11;
}

.stock-chip.is-empty {
  color: #a83434;
}

.stock-chip.is-healthy {
  color: var(--success);
}

.stock-chip.is-new {
  color: var(--accent-text);
}

.stock-chip.is-near-expiry {
  color: #9a6700;
}

.stock-chip.is-expired {
  color: #a83434;
}

.stock-meter {
  height: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(var(--accent-rgb), 0.1);
}

.stock-meter__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
}

.stock-meter__fill.is-low {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
}

.stock-meter__fill.is-critical {
  background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%);
}

.stock-meter__fill.is-empty {
  background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%);
}

.stock-meter__fill.is-healthy {
  background: linear-gradient(135deg, #22c55e 0%, #15803d 100%);
}

.stock-product-card__meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  position: relative;
  margin-inline: -18px;
  padding: 16px 18px 0;
}

.stock-product-card__meta::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: rgba(15, 23, 42, 0.14);
}

.stock-product-card__meta .dashboard-info-row {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: flex-start;
  flex-direction: row;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 0;
  border-radius: 8px;
  background: transparent;
}

.stock-product-card__meta .dashboard-info-row strong {
  overflow-wrap: anywhere;
  font-size: 16px;
  line-height: 1.35;
  font-weight: 600;
}

.stock-product-card__meta-row--stocked-date strong {
  white-space: nowrap;
  overflow-wrap: normal;
  word-break: normal;
}

.stock-product-card__meta-row--stocked-date strong[data-stock-time-tooltip],
.stock-variant-card__meta-item--stocked-date .stock-variant-card__meta-value[data-stock-time-tooltip] {
  position: relative;
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  outline: none;
}

.stock-product-card__meta-row--stocked-date strong[data-stock-time-tooltip]::after,
.stock-variant-card__meta-item--stocked-date .stock-variant-card__meta-value[data-stock-time-tooltip]::after {
  content: attr(data-stock-time-tooltip);
  position: absolute;
  top: 50%;
  left: calc(100% + 14px);
  transform: translateY(-50%) translateX(-4px);
  padding: 8px 12px;
  border: 0;
  border-radius: 10px;
  background: linear-gradient(
    135deg,
    rgba(var(--accent-rgb), 0.96) 0%,
    rgba(var(--accent-rgb), 0.78) 100%
  );
  color: var(--accent-contrast);
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  box-shadow: 0 12px 24px rgba(var(--accent-rgb), 0.24);
  backdrop-filter: blur(12px);
  transition:
    opacity 140ms ease,
    visibility 140ms ease,
    transform 180ms ease;
  transition-delay: 0s;
  z-index: 280;
}

@media (hover: hover) and (pointer: fine) {
  .stock-product-card__meta-row--stocked-date strong[data-stock-time-tooltip]:hover::after,
  .stock-product-card__meta-row--stocked-date strong[data-stock-time-tooltip]:focus-visible::after,
  .stock-variant-card__meta-item--stocked-date .stock-variant-card__meta-value[data-stock-time-tooltip]:hover::after,
  .stock-variant-card__meta-item--stocked-date .stock-variant-card__meta-value[data-stock-time-tooltip]:focus-visible::after {
    opacity: 1;
    visibility: visible;
    transform: translateY(-50%) translateX(0);
    transition-delay: 0.5s;
  }
}

.stock-product-card__meta-value-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.stock-product-card__meta-subvalue {
  display: block;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.35;
}

.stock-product-card__meta-copy {
  min-width: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
}

.stock-product-card__meta-label-icon {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex: 0 0 auto;
}

.stock-product-card__meta-row--stock .stock-product-card__meta-label-icon {
  width: 40px;
  height: 40px;
}

.stock-product-card__meta-label-text {
  display: block;
  font-size: 16px;
  font-weight: 500;
  letter-spacing: 0.02em;
  line-height: 1.2;
  text-transform: none;
}

.stock-product-card__meta-label-icon svg {
  width: 100%;
  height: 100%;
  display: block;
}

.stock-product-card__meta-row--expiry {
  position: relative;
  gap: 8px;
}

.stock-product-card__meta-date-trigger {
  width: 100%;
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  transition: none !important;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  text-align: left;
}

.stock-product-card__meta-date-trigger.is-empty {
  color: var(--text-secondary);
}

.stock-product-card__meta-date-trigger:hover,
.stock-product-card__meta-date-trigger:active {
  background: transparent !important;
  color: var(--text-primary) !important;
  box-shadow: none !important;
  transform: none !important;
}

.stock-product-card__meta-date-trigger.is-empty:hover,
.stock-product-card__meta-date-trigger.is-empty:active {
  color: var(--text-secondary) !important;
}

.stock-product-card__meta-date-trigger:focus-visible,
.stock-product-card__meta-row--expiry.is-open .stock-product-card__meta-date-trigger {
  color: var(--accent-text);
  outline: none;
}

.stock-product-card__meta-date-value {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
}

.stock-product-card__meta-date-trigger-icon {
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  flex: 0 0 auto;
}

.stock-product-card__meta-date-trigger:hover .stock-product-card__meta-date-trigger-icon,
.stock-product-card__meta-date-trigger:active .stock-product-card__meta-date-trigger-icon {
  color: var(--text-secondary) !important;
  transform: none !important;
}

.stock-product-card__meta-date-trigger:focus-visible .stock-product-card__meta-date-trigger-icon,
.stock-product-card__meta-row--expiry.is-open .stock-product-card__meta-date-trigger-icon {
  color: var(--accent-text);
}

.stock-product-card__meta-date-trigger-icon svg {
  width: 100%;
  height: 100%;
  display: block;
}

.stock-product-card__calendar-popover {
  top: calc(100% + 10px);
}

.stock-detail-panel__header {
  display: grid;
  gap: 6px;
  margin-bottom: 16px;
}

.stock-detail-panel__eyebrow {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.stock-detail-panel__title {
  margin: 0;
  font-size: 22px;
  line-height: 1.2;
}

.stock-detail-panel__copy {
  margin: 0;
  color: var(--text-secondary);
  line-height: 1.5;
}

.stock-detail-panel__table-shell {
  overflow-x: auto;
  border-radius: 8px;
  background: transparent;
}

.stock-detail-table {
  width: 100%;
  min-width: 600px;
  border-collapse: collapse;
  table-layout: fixed;
}

.stock-detail-table th,
.stock-detail-table td {
  padding: 12px 10px;
  text-align: center;
  vertical-align: middle;
}

.stock-detail-table th {
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
  background: transparent;
}

.stock-detail-table td {
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
