  line-height: 1.5;
}

.stock-detail-table th:first-child,
.stock-detail-table td:first-child {
  padding-left: 10px;
  padding-right: 10px;
}

.stock-detail-table th:last-child,
.stock-detail-table td:last-child {
  padding-left: 10px;
  padding-right: 10px;
}

.stock-detail-table__meta {
  margin-top: 4px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.4;
  white-space: nowrap;
}

.stock-detail-table__meta--warning {
  color: #9a6700;
