}

.stock-detail-table__col--stocks {
  width: 11%;
}

.stock-detail-table__col--quantity {
  width: 11%;
}

.stock-detail-table__col--modified {
  width: 21%;
}

.stock-detail-table__col--expiry {
  width: 16%;
}

.stock-detail-table__col--reason {
  width: 20%;
}

.stock-detail-table__col--label {
