.stock-monitor-shell .stock-detail-table__row.is-notification-focus-pop td.stock-detail-table__adjustment--deducted,
.stock-monitor-shell .dashboard-content.is-stock-notification-focus-active .stock-detail-panel__table-shell.is-stock-notification-record-focus-pop .stock-detail-table__row.is-stock-notification-focus-pop td.stock-detail-table__adjustment--deducted {
  color: #a83434 !important;
}

.stock-monitor-shell .stock-detail-table__cell.is-notification-focus-pop {
  animation: stock-record-notification-text-pop 1.55s ease both;
  transform-origin: left center;
  border-radius: 8px;
  background: rgba(var(--accent-rgb), 0.14);
  color: var(--accent-text);
  font-weight: 700;
  box-shadow:
    0 14px 30px rgba(var(--accent-rgb), 0.16),
    0 0 0 4px rgba(var(--accent-rgb), 0.08);
}

.stock-monitor-shell .stock-detail-table__cell--expiry.is-notification-focus-pop {
  transform-origin: center;
}

.stock-detail-table__label {
  display: inline-flex;
  align-items: center;
  padding: 5px 10px;
  border-radius: 999px;
  background: transparent;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
}

.stock-detail-table__label--new {
  color: #20603a;
}

.stock-detail-table__label--old {
  color: #8a5a06;
}

.stock-detail-table td.stock-detail-table__adjustment--deducted {
  color: #a83434;
  font-weight: inherit;
}

.stock-detail-table__label-cell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  justify-items: center;
  gap: 8px;
  width: 100%;
  min-height: 32px;
}

.stock-detail-table__delete-button {
  width: 40px;
  min-width: 40px;
  min-height: 40px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: transparent;
  border: none;
  box-shadow: none;
  border-radius: 0;
  color: #a83434;
}

.stock-detail-table__delete-button i {
  font-size: 18px;
  line-height: 1;
}

.stock-detail-table__delete-button:hover,
.stock-detail-table__delete-button:focus-visible {
  background: transparent;
  border: none;
  box-shadow: none;
  color: #922d2d;
}

.stock-detail-table__delete-button:disabled,
.stock-detail-table__delete-button.is-saving {
