.stock-edit-modal__actions {
  margin-inline: -24px;
  padding-top: 16px;
  padding-inline: 24px;
  border-top: 1px solid rgba(15, 23, 42, 0.08);
}

.stock-edit-modal__list .dashboard-info-row strong {
  display: block;
  width: 100%;
  padding: 14px 16px;
  border-radius: 8px;
  background: #f3f4f6;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
}

