  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.main-notification-show-all:hover,
.main-notification-show-all:focus-visible {
  background: rgba(15, 23, 42, 0.055);
  outline: none;
}

.main-notification-panel.is-expanded {
  grid-template-rows: auto auto auto;
}

.main-notification-panel.is-expanded.is-scrollable {
  height: var(--main-notification-expanded-height, calc(100dvh - 100px));
