.main-live-chat-view {
  --live-chat-ink: #101828;
  --live-chat-muted: #667085;
  --live-chat-line: #e6edf7;
  --live-chat-soft: #f6f8fc;
  --live-chat-soft-blue: rgba(var(--main-accent-rgb), 0.08);
  --live-chat-accent: var(--main-accent);
  --live-chat-accent-rgb: var(--main-accent-rgb);
  --live-chat-surface: #ffffff;
  --live-chat-surface-hover: #f8fafc;
  --live-chat-border: #e2e8f0;
  --live-chat-shadow: 0 4px 12px rgba(0, 0, 0, 0.08);
  --live-chat-shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.12);
  --live-chat-radius: 12px;
  --live-chat-radius-sm: 8px;
  --live-chat-radius-lg: 16px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  height: calc(100dvh - 82px);
  min-height: 680px;
  margin: 0;
  padding: 0;
  overflow: hidden;
  box-sizing: border-box;
  font-family: "Poppins", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: linear-gradient(135deg, #f8fafc 0%, #ffffff 50%, #f1f5f9 100%);
}

.main-live-chat-mount {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

/* Live Chat Topbar Styling */
body .main-live-chat-view .live-chat-topbar {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border-bottom: 1px solid var(--live-chat-line);
  padding: 12px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 64px;
}

body .main-live-chat-view .live-chat-topbar__left {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
}

body .main-live-chat-view .live-chat-topbar__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

body .main-live-chat-view .live-chat-topbar__icon-button {
  width: 40px;
  height: 40px;
  border-radius: var(--live-chat-radius-sm);
  background: var(--live-chat-surface);
  border: 1px solid var(--live-chat-border);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
  color: var(--live-chat-ink);
}

body .main-live-chat-view .live-chat-topbar__icon-button:hover {
  background: var(--live-chat-soft);
  border-color: var(--live-chat-accent);
  color: var(--live-chat-accent);
  transform: translateY(-1px);
}

body .main-live-chat-view .live-chat-topbar__app-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--live-chat-radius);
  background: linear-gradient(135deg, var(--live-chat-accent) 0%, #1d4ed8 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-size: 20px;
  box-shadow: 0 2px 8px rgba(var(--live-chat-accent-rgb), 0.3);
}

body .main-live-chat-view .live-chat-topbar__status-dot {
  position: absolute;
  bottom: 2px;
  right: 2px;
  width: 10px;
  height: 10px;
  background: #22c55e;
  border: 2px solid var(--live-chat-surface);
  border-radius: 50%;
}

body .main-live-chat-view .live-chat-topbar__search {
  flex: 1;
  max-width: 320px;
  position: relative;
}

body .main-live-chat-view .live-chat-topbar__search input {
  width: 100%;
  padding: 10px 16px 10px 42px;
  border: 1px solid var(--live-chat-border);
  border-radius: var(--live-chat-radius);
  background: var(--live-chat-soft);
  font-size: 14px;
  color: var(--live-chat-ink);
  transition: all 0.2s ease;
}

body .main-live-chat-view .live-chat-topbar__search input:focus {
  outline: none;
  border-color: var(--live-chat-accent);
  background: var(--live-chat-surface);
  box-shadow: 0 0 0 3px rgba(var(--live-chat-accent-rgb), 0.1);
}

body .main-live-chat-view .live-chat-topbar__search i {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--live-chat-muted);
  font-size: 14px;
}

/* Live Chat Workspace */
body .main-live-chat-view .live-chat-workspace {
  display: flex;
  height: calc(100% - 64px);
  background: var(--live-chat-surface);
  overflow: hidden;
}

/* Thread Column (Left Sidebar) */
body .main-live-chat-view .employee-chat-thread-column {
  width: 320px;
  min-width: 280px;
  max-width: 360px;
  border-right: 1px solid var(--live-chat-line);
  display: flex;
  flex-direction: column;
  background: var(--live-chat-surface);
}

body .main-live-chat-view .live-chat-thread-header {
  padding: 16px;
  border-bottom: 1px solid var(--live-chat-line);
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
}

body .main-live-chat-view .live-chat-thread-titlebar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

body .main-live-chat-view .live-chat-thread-title {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: none;
  background: transparent;
  font-size: 16px;
  font-weight: 600;
  color: var(--live-chat-ink);
  cursor: pointer;
  border-radius: var(--live-chat-radius-sm);
  transition: all 0.2s ease;
}

body .main-live-chat-view .live-chat-thread-title:hover {
  background: var(--live-chat-soft);
}

body .main-live-chat-view .live-chat-thread-compose {
  width: 36px;
  height: 36px;
  border-radius: var(--live-chat-radius-sm);
  background: linear-gradient(135deg, var(--live-chat-accent) 0%, #1d4ed8 100%);
  border: none;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 2px 6px rgba(var(--live-chat-accent-rgb), 0.25);
}

