/* === Consolidated Admin Seller summary cards === */
/* Shared Super Admin summary card design for Admin Seller workspaces. */

:root {
  --admin-seller-summary-shadow: 0 18px 36px rgba(15, 23, 42, 0.06);
  --admin-seller-summary-shadow-hover: 0 18px 36px rgba(15, 23, 42, 0.1);
  --admin-seller-summary-shadow-active: 0 18px 36px rgba(var(--accent-rgb, 37, 99, 235), 0.12);
  --admin-seller-summary-border: 1px solid rgba(15, 23, 42, 0.08);
}

.super-admin-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 12px;
}

.super-admin-stat {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  grid-template-areas:
    "icon label"
    "icon value"
    "icon trend";
  column-gap: 12px;
  row-gap: 5px;
  align-items: center;
  min-width: 0;
  padding: 16px;
  border: var(--admin-seller-summary-border);
  border-radius: 8px;
  background: #ffffff;
  box-shadow: var(--admin-seller-summary-shadow);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.super-admin-stat span {
  color: var(--text-secondary, #52607a);
  font-size: 12px;
  margin-right: 4px;
  font-weight: 500;
}

.super-admin-stat__label {
  grid-area: label;
  align-self: end;
  line-height: 1.2;
}

.super-admin-stat .super-admin-stat__icon {
  grid-area: icon;
  display: inline-grid;
  place-items: center;
  align-self: start;
  width: 44px;
  height: 44px;
  padding-top: 19px;
  border-radius: 999px;
  background: #ffffff;
  color: var(--accent, #2563eb);
  text-transform: none;
}

.super-admin-stat .super-admin-stat__icon svg {
  width: 30px;
  height: 30px;
}

.super-admin-stat strong {
  grid-area: value;
  align-self: start;
  color: var(--text-primary, #162033);
  font-size: 30px;
  line-height: 1;
  font-weight: 500;
}

.super-admin-stat__trend {
  grid-area: trend;
  align-self: start;
  min-width: 0;
}

.super-admin-stat__trend-value,
.super-admin-stat__trend-period {
  display: inline;
}

.super-admin-stat__trend.is-neutral .super-admin-stat__trend-value {
  margin-right: 4px;
}

.super-admin-stat .super-admin-stat__trend.is-up .super-admin-stat__trend-value {
  color: #15803d;
  margin-right: 4px;
}

.super-admin-stat .super-admin-stat__trend.is-down .super-admin-stat__trend-value {
  color: #b91c1c;
  margin-right: 4px;
}

button.super-admin-stat {
  width: 100%;
  margin: 0;
  text-align: left;
  cursor: pointer;
  font: inherit;
  appearance: none;
  color: inherit;
}

button.super-admin-stat:hover,
button.super-admin-stat:focus-visible {
  border-color: rgba(var(--accent-rgb, 37, 99, 235), 0.24);
  outline: none;
  box-shadow: var(--admin-seller-summary-shadow-hover);
}

button.super-admin-stat.is-active {
  border-color: rgba(var(--accent-rgb, 37, 99, 235), 0.34);
  box-shadow: var(--admin-seller-summary-shadow-active);
}

.super-admin-stat[data-admin-summary-tone="total"] .super-admin-stat__icon,
.super-admin-stat[data-admin-summary-tone="all"] .super-admin-stat__icon {
  color: var(--accent, #2563eb);
}

.super-admin-stat[data-admin-summary-tone="active"] .super-admin-stat__icon {
  color: #15803d;
}

.super-admin-stat[data-admin-summary-tone="inactive"] .super-admin-stat__icon {
  color: #64748b;
}

.super-admin-stat[data-admin-summary-tone="online"] .super-admin-stat__icon,
.super-admin-stat[data-admin-summary-tone="live"] .super-admin-stat__icon {
  color: #346e90;
}

.super-admin-stat[data-admin-summary-tone="pending"] .super-admin-stat__icon,
