.super-admin-stat[data-admin-summary-tone="revision"] .super-admin-stat__icon,
.super-admin-stat[data-admin-summary-tone="restricted"] .super-admin-stat__icon,
.super-admin-stat[data-admin-summary-tone="banned"] .super-admin-stat__icon {
