  --table-row-hover-bg: rgba(var(--employee-accent-rgb), 0.055);
  --table-row-hover-shadow: inset 3px 0 0 rgba(var(--employee-accent-rgb), 0.55);
  --employee-danger: #cf3f50;
  --employee-font: "Poppins", "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
}


html:has(body.employee-workspace-page),
body.employee-workspace-page {
  width: 100%;
  min-width: 0;
  min-height: 100%;
  margin: 0;
  color: var(--employee-ink);
  font-family: var(--employee-font);
}

body.employee-workspace-page {
  overflow-x: hidden;
}

body.employee-layer-open {
  overflow: hidden;
}

body.employee-workspace-page button,
body.employee-workspace-page input,
body.employee-workspace-page select {
  font: inherit;
}

body.employee-workspace-page button,
body.employee-workspace-page select {
  cursor: pointer;
}

body.employee-workspace-page button:focus-visible,
body.employee-workspace-page input:focus-visible,
body.employee-workspace-page select:focus-visible,
body.employee-workspace-page a:focus-visible {
  outline: 2px solid rgba(8, 152, 157, 0.32);
  outline-offset: 2px;
}

body.employee-workspace-page [hidden] {
  display: none !important;
}

.employee-workspace {
  width: 100%;
  max-width: none;
  min-width: 0;
  display: grid;
  gap: 14px;
}

.employee-workspace__header {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.employee-workspace__header h1 {
  margin: 0;
  font-size: 23px;
  line-height: 1.25;
  letter-spacing: 0;
}

.employee-workspace__header p {
  margin: 4px 0 0;
  color: var(--employee-muted);
  font-size: 12px;
}

.employee-command {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 13px;
  border: 1px solid #d9e0e7;
  border-radius: 6px;
  background: #ffffff;
  color: #344054;
  font-weight: 700;
}

.employee-command svg {
  width: 22px;
  height: 22px;
}

.employee-command:hover {
  border-color: #82c9cc;
  color: var(--employee-accent-dark);
}

.employee-command--primary {
  border-color: var(--employee-accent);
  background: var(--employee-accent);
  color: #ffffff;
}

.employee-command--primary:hover {
  border-color: var(--employee-accent-dark);
  background: var(--employee-accent-dark);
  color: #ffffff;
}

.employee-command:disabled {
  opacity: 0.58;
  cursor: wait;
}

.employee-summary {
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.employee-summary-card {
  min-width: 0;
  min-height: 102px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 11px;
  padding: 14px;
  border-radius: 7px;
  background: var(--employee-panel);
}

.employee-summary-card__icon {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #1686a7;
}

.employee-summary-card.is-active .employee-summary-card__icon {
  color: #24a060;
}

.employee-summary-card.is-leave .employee-summary-card__icon {
  color: #da9a05;
}

.employee-summary-card.is-inactive .employee-summary-card__icon {
  color: #d14555;
}

.employee-summary-card.is-new .employee-summary-card__icon {
  color: #7658d6;
}

.employee-summary-card__icon svg {
  width: 30px;
  height: 30px;
}

.employee-summary-card__copy {
  min-width: 0;
  display: grid;
}

.employee-summary-card__copy span, .employee-summary-card__copy small {
  overflow: hidden;
  color: #52607a;
  font-size: 12px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stock-edit-modal__title
.employee-summary-card__copy strong {
  font-size: 28px;
  font-weight: 500;
  line-height: 1.1;
}

.employee-directory {
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  border-radius: 7px;
  background: var(--employee-panel);
  overflow: hidden;
}

.employee-directory__toolbar {
  min-width: 0;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--employee-line);
}

.employee-search {
  width: min(360px, 100%);
  min-height: 38px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 11px;
  border: 1px solid #dbe1e8;
  border-radius: 6px;
  background: #ffffff;
}

.employee-search:focus-within {
  border-color: #72bec2;
  box-shadow: 0 0 0 3px rgba(8, 152, 157, 0.08);
}

.employee-search svg {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  color: #667085;
}

.employee-search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  color: var(--employee-ink);
  font-size: 11px;
}

.employee-directory__filters {
  display: flex;
  gap: 8px;
}

.employee-directory__filters label {
  display: grid;
  gap: 3px;
  color: var(--employee-muted);
  font-size: 8px;
  font-weight: 700;
}

.employee-directory__filters select {
  min-width: 145px;
  min-height: 36px;
  padding: 6px 30px 6px 9px;
  border: 1px solid #dbe1e8;
  border-radius: 6px;
  background: #ffffff;
  color: #344054;
  font-size: 10px;
}

.employee-table-shell {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  overflow-x: auto;
  border: 0;
  border-radius: 8px;
  background: #ffffff;
  box-sizing: border-box;
}

.employee-table__check {
  width: 14px;
  height: 14px;
  display: block;
  border: 1px solid #cfd7e1;
  border-radius: 3px;
}

.employee-table {
  width: 100%;
  min-width: 1050px;
  display: grid;
  grid-template-columns: 0px 116px minmax(190px, 1.35fr) 125px 145px 142px 105px 86px 94px;
  align-items: center;
  gap: 8px;
  padding: 0px 14px;
}

.employee-table__body {
  width: 100%;
  min-width: 1050px;
  border-radius: 0 0 8px 8px;
  overflow: hidden;
  background: #ffffff;
}

.employee-row {
  min-height: 70px;
  border-bottom: 1px solid #edf0f4;
  color: #344054;
  font-size: 9px;
  cursor: pointer;
  transition: background-color 140ms ease, box-shadow 140ms ease;
}

.employee-row:hover,
.employee-row:focus-within,
.employee-row:focus-visible {
  background: var(--table-row-hover-bg);
  box-shadow: var(--table-row-hover-shadow);
  outline: 0;
}

.employee-row:last-child {
  border-bottom: 0;
}

.employee-row > span, .employee-row > div {
  min-width: 0;
  font-size: 12px;
  font-weight: 500px;
}

.employee-row__id,
.employee-row__contact,
.employee-row__date,
.employee-row__department,
.employee-row__position {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.employee-row__person {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  align-content: center;
  gap: 12px;
  min-width: 0;
  min-height: 100%;
}

.employee-avatar {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  align-self: center;
  justify-self: center;
  overflow: hidden;
  border-radius: 999px;
  background: #eef2f6;
  color: #526075;
  font-size: 13px;
  font-weight: 800;
  flex-shrink: 0;
  line-height: 1;
}

.employee-avatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.employee-row__person-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.employee-row__person-copy strong,
.employee-row__person-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.employee-row__person-copy strong {
  color: #101828;
  font-size: 12px;
  font-weight: 500;
}

.employee-row__person-copy small {
  color: var(--employee-muted);
  font-size: 11px;
}

.employee-status-pill {
  height: 9px;
  width:  9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: #16824d;
  font-size: 8px;
  font-weight: 700;
  white-space: nowrap;
}

.employee-status-pill.is-on-leave {
  background: #fff4d8;
  color: #aa7200;
}

.employee-status-pill.is-inactive {
  background: #fdecef;
  color: #c63848;
}

.employee-status-pill.is-probation {
  background: #f0edff;
  color: #6d55c6;
}

.employee-row__actions {
  display: inline-flex;
  justify-content: flex-end;
  align-items: center;
  align-self: center;
  justify-self: end;
  gap: 4px;
  min-width: 0;
  opacity: 0;
  visibility: hidden;
  transform: translateX(8px);
  pointer-events: none;
  transition: opacity 150ms ease, transform 150ms ease, visibility 150ms ease;
}

.employee-row:hover .employee-row__actions,
.employee-row:focus-within .employee-row__actions {
  opacity: 1;
  visibility: visible;
  transform: translateX(0);
  pointer-events: auto;
}

.employee-icon-button {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  display: inline-grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent !important;
  color: #64748b;
  box-shadow: none;
  cursor: pointer;
}

.employee-icon-button:hover,
.employee-icon-button:focus-visible {
  background: transparent !important;
  color: var(--accent, var(--employee-accent-dark, #0f9f78));
  outline: 0;
}

.employee-icon-button.is-danger,
.employee-icon-button.is-danger svg {
  color: #b91c1c;
}

.employee-icon-button.is-danger:hover,
.employee-icon-button.is-danger:focus-visible {
  background: transparent !important;
  color: #991b1b;
}

.employee-icon-button svg {
  width: 18px;
  height: 18px;
}

.employee-loading,
.employee-empty {
  min-height: 300px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 10px;
  padding: 30px;
  color: var(--employee-muted);
  font-size: 11px;
  text-align: center;
}

.employee-loading > span {
  width: 26px;
  height: 26px;
  border: 3px solid #dceef0;
  border-top-color: var(--employee-accent);
  border-radius: 50%;
  animation: employee-spin 700ms linear infinite;
}

@keyframes employee-spin {
  to { transform: rotate(360deg); }
}

.employee-pagination {
  min-height: 50px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 14px;
  background: #f2f2f2;
  color: var(--employee-muted);
  font-size: 11px;
  font-size: 400;
}

.employee-pagination__buttons {
  display: flex;
  gap: 5px;
}

.employee-pagination__buttons button {
  width: 32px;
  min-width: 32px;
  height: 32px;
  min-height: 32px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid #e5e7eb;
  border-radius: 5px;
  background: #ffffff;
  color: #4b5563;
  font-size: 10px;
  font-weight: 700;
}

.employee-pagination__buttons button:hover:not(:disabled),
.employee-pagination__buttons button:focus-visible:not(:disabled),
.employee-pagination__buttons button.is-active {
  border-color: var(--employee-accent);
  background: linear-gradient(135deg, var(--employee-accent), var(--employee-accent-dark));
  color: #ffffff;
  outline: none;
}

.employee-pagination__buttons button svg {
  width: 15px;
  height: 15px;
}

.employee-pagination__buttons button:disabled {
  opacity: 0.4;
  cursor: default;
}

.employee-drawer-overlay,
.employee-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(15, 23, 42, 0.18);
  opacity: 0;
  transition: opacity 180ms ease;
}

.employee-drawer-overlay.is-open,
.employee-modal-overlay.is-open {
  opacity: 1;
}

.employee-drawer {
  position: absolute;
  inset: 0 0 0 auto;
  width: min(350px, 100%);
  min-width: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  background: #ffffff;
  border-left: 1px solid #e5e7eb;
  box-shadow: -18px 0 48px rgba(15, 23, 42, 0.12);
  color: #111827;
  transform: translateX(18px);
  opacity: 0;
  transition: transform 180ms cubic-bezier(0.22, 1, 0.36, 1), opacity 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.employee-drawer-overlay.is-open .employee-drawer {
  transform: translateX(0);
  opacity: 1;
}

.employee-drawer__header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 64px;
  padding: 18px 20px;
  border-bottom: 0;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  background: rgba(255, 255, 255, 0.92);
}

.employee-drawer__header h2 {
  margin: 0;
  color: #111827;
  font-size: 20px;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0;
}

.employee-drawer__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  min-width: 40px;
  min-height: 40px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: #ffffff;
  color: #0f172a;
  box-shadow: none;
  cursor: pointer;
  transition: background 140ms ease, color 140ms ease;
}

.employee-drawer__close:hover,
.employee-drawer__close:focus-visible {
  background: #4b5563;
  color: #ffffff;
  outline: none;
}

.employee-drawer__close svg {
  width: 18px;
  height: 18px;
}

.employee-drawer__content {
  min-height: 0;
  overflow-y: auto;
  padding: 8px 24px 28px;
  scrollbar-width: thin;
  scrollbar-color: #cbd5e1 transparent;
}

.employee-drawer__content::-webkit-scrollbar {
  width: 6px;
}

.employee-drawer__content::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: #cbd5e1;
}

.employee-drawer__summary {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  align-items: center;
  gap: 16px;
  padding: 4px 4px 22px;
  text-align: left;
}

.employee-drawer__logo-wrap {
  position: relative;
  width: 72px;
  height: 72px;
  flex: 0 0 72px;
}

.employee-drawer__logo.employee-avatar,
.employee-drawer-profile .employee-avatar,
.employee-drawer__summary .employee-avatar {
  position: relative;
  width: 72px;
  height: 72px;
  font-size: 16px;
  overflow: hidden;
}

.employee-drawer__logo.employee-avatar img,
.employee-drawer__summary .employee-avatar img {
  border-radius: 999px;
  overflow: hidden;
}

.employee-drawer__profile-status {
  position: absolute;
  right: -1px;
  bottom: -1px;
  z-index: 3;
  width: 15px;
  height: 15px;
  border: 2px solid #ffffff;
  border-radius: 999px;
  background: #94a3b8;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.2);
}

.employee-drawer__profile-status.is-success,
.employee-drawer__profile-status.is-online {
  background: #22c55e;
}

.employee-drawer__profile-status.is-warning {
  background: #f59e0b;
}

.employee-drawer__profile-status.is-danger {
  background: #ef4444;
}

.employee-drawer__profile-status.is-info {
  background: #3b82f6;
}

.employee-drawer__summary-copy {
  display: grid;
  justify-items: start;
  gap: 5px;
  min-width: 0;
}

.employee-drawer__summary-copy strong {
  overflow: hidden;
  width: 100%;
  color: #111827;
  font-size: 15px;
  font-weight: 800;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.employee-drawer__summary-copy span {
  overflow: hidden;
  width: 100%;
  color: #64748b;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.employee-drawer__overview {
  display: grid;
  gap: 2px;
  padding: 18px 0;
  border-bottom: 1px solid #edf0f4;
}

.employee-drawer__overview-row {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  min-height: 39px;
}

.employee-drawer__overview-icon {
  display: inline-grid;
  place-items: center;
  color: #64748b;
}

.employee-drawer__overview-icon svg {
  width: 18px;
  height: 18px;
}

.employee-drawer__overview-label {
  color: #4b5563;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.2;
}

.employee-drawer__status-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  max-width: 160px;
  min-height: 24px;
  padding: 0 9px;
  overflow: hidden;
  border-radius: 7px;
  background: #f1f5f9;
  color: #64748b;
  font-size: 12px;
  font-weight: 500;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.employee-drawer__status-chip.is-success {
  background: #ecfdf5;
  color: #059669;
}

.employee-drawer__status-chip.is-warning {
  background: #fffbeb;
  color: #b45309;
}

.employee-drawer__status-chip.is-danger {
  background: #fff1f2;
  color: #e11d48;
}

.employee-drawer__status-chip.is-info {
  background: #eff6ff;
  color: #2563eb;
}

.employee-drawer__information {
  display: grid;
  gap: 13px;
  padding: 18px 0 20px;
  border-bottom: 1px solid #edf0f4;
}

.employee-drawer__info-row {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  align-items: start;
  gap: 12px;
}

.employee-drawer__info-label {
  color: #64748b;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.45;
}

.employee-drawer__info-value {
  color: #475569;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.employee-drawer__section {
  display: grid;
  gap: 9px;
  padding-top: 20px;
}

.employee-drawer__section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.employee-drawer__section-heading h3 {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
}

.employee-detail-list {
  display: grid;
  gap: 8px;
  margin: 0;
}

.employee-detail-list > div {
  min-width: 0;
  display: grid;
  grid-template-columns: 105px minmax(0, 1fr);
  gap: 8px;
}

.employee-detail-list dt,
.employee-detail-list dd {
  margin: 0;
  font-size: 9px;
  line-height: 1.45;
}

.employee-detail-list dt {
  color: var(--employee-muted);
}

.employee-detail-list dd {
  overflow-wrap: anywhere;
  color: #344054;
  font-weight: 600;
}

.employee-document-list {
  display: grid;
  gap: 7px;
}

.employee-document {
  min-width: 0;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  color: #344054;
  font-size: 12px;
}

.employee-document svg {
  width: 15px;
  height: 15px;
  color: #64748b;
}

.employee-document span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.employee-document small {
  color: #98a2b3;
  white-space: nowrap;
}

.employee-document a {
  color: #16824d;
  font-weight: 700;
  text-decoration: none;
}

.employee-drawer__actions-grid {
  display: grid;
  gap: 4px;
}

.employee-drawer__action-button {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  width: 100%;
  min-height: 38px;
  margin: 0;
  padding: 0 8px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #111827;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  box-shadow: none;
}

.employee-drawer__action-button svg {
  width: 18px;
  height: 18px;
  color: #64748b;
  flex: 0 0 auto;
}

.employee-drawer__action-button:hover,
.employee-drawer__action-button:focus-visible {
  background: rgba(var(--accent-rgb, 15, 159, 120), 0.07);
  color: var(--text-primary, #111827);
  outline: none;
}

.employee-drawer__action-button--primary {
  color: var(--employee-accent, #0f9f78);
}

.employee-drawer__action-button--primary svg {
  color: currentColor;
}

.employee-drawer__actions {
