.main-nav__sublist {
  --main-subnav-expanded-height: 220px;
  --main-subnav-row-height: 29px;
  --main-subnav-padding-block: 2px;
  position: relative;
  display: grid;
  gap: 2px;
  max-height: 0;
  margin: 0 0 0 21px;
  padding: 0;
  border: 0;
  opacity: 1;
  overflow: hidden;
  pointer-events: none;
  transform: none;
  transition:
    max-height 240ms cubic-bezier(0.22, 1, 0.36, 1),
    margin-top 240ms cubic-bezier(0.22, 1, 0.36, 1),
    margin-bottom 240ms cubic-bezier(0.22, 1, 0.36, 1),
    padding 240ms cubic-bezier(0.22, 1, 0.36, 1);
  will-change: max-height, padding, margin;
}

.main-nav__sublist.is-open:not(.is-collapsed) {
  max-height: var(--main-subnav-expanded-height);
  margin: -2px 0 6px 21px;
  padding: var(--main-subnav-padding-block) 0;
