  content: "";
  position: absolute;
  top: 16.5px;
  bottom: 16.5px;
  left: 5px;
  width: 1px;
  border-radius: 999px;
  background: #d8e0ec;
  opacity: 1;
  transform: scaleY(1);
  transform-origin: top;
  pointer-events: none;
  transition: none;
}

.main-nav__sublist.is-collapsed::before {
  opacity: 0;
  transform: scaleY(0);
}

