.product-expiry-calendar {
  --product-expiry-calendar-accent: var(--accent, #2563eb);
  position: fixed;
  /* The composer portal uses z-index 2000 and creates an isolated stacking
     context, so the body-level calendar must sit above that overlay. */
  z-index: 2100;
  width: min(304px, calc(100vw - 24px));
  padding: 12px;
  border: 1px solid #dbe3ee;
  border-radius: 10px;
  background: #ffffff;
  color: #11213d;
  box-shadow: 0 18px 44px rgba(15, 23, 42, 0.2);
  font-family: "Poppins", "TikTok Sans", sans-serif;
}

