}

.product-expiry-calendar::before,
.product-expiry-calendar::after {
  position: absolute;
  left: var(--product-expiry-calendar-arrow-left, 50%);
  width: 0;
  height: 0;
  border-right: 8px solid transparent;
  border-left: 8px solid transparent;
  content: "";
  transform: translateX(-50%);
}

.product-expiry-calendar::before {
  top: -9px;
  border-bottom: 9px solid #dbe3ee;
}

.product-expiry-calendar::after {
  top: -8px;
  border-bottom: 9px solid #ffffff;
}

.product-expiry-calendar.is-open-up::before {
  top: auto;
  bottom: -9px;
  border-top: 9px solid #dbe3ee;
  border-bottom: 0;
}

.product-expiry-calendar.is-open-up::after {
