/* Admin Seller header filters mirror the Super Admin filter-by control. */
body.main-shell-host .main-orders-header-filter {
  position: relative;
  z-index: 340;
  flex: 0 0 auto;
  width: max-content;
  max-width: 100%;
}

body.main-shell-host .main-orders-header-filter[hidden],
body.main-shell-host .main-orders-header-filter__panel[hidden],
body.main-shell-host .main-orders-header-filter__date-range[hidden] {
  display: none !important;
}

body.main-shell-host .main-orders-header-filter__trigger {
  width: max-content;
  max-width: 100%;
  white-space: nowrap;
}

body.main-shell-host .main-orders-header-filter__trigger > span {
  flex: 0 0 auto;
  min-width: max-content;
  white-space: nowrap;
}

body.main-shell-host .main-orders-header-filter__panel {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  z-index: 120;
  display: flex;
  flex-direction: column;
  gap: 0;
  width: min(760px, calc(100vw - 32px));
  max-height: min(72vh, 640px);
  padding: 0;
  overflow: hidden;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 18px 52px rgba(15, 23, 42, 0.12);
  transform-origin: top left;
}

body.main-shell-host .main-orders-header-filter__body {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  min-height: 0;
  padding: 12px;
  overflow-x: hidden;
  overflow-y: auto;
}

body.main-shell-host .main-orders-header-filter__section {
  display: grid;
}

body.main-shell-host .main-orders-header-filter__column {
  display: grid;
  align-content: start;
  gap: 14px;
  min-width: 0;
}

body.main-shell-host .main-orders-header-filter__column .main-orders-header-filter__section + .main-orders-header-filter__section {
  padding-top: 14px;
}

body.main-shell-host .main-orders-header-filter__dynamic-options {
  display: grid;
  max-width: 100%;
  max-height: none;
  overflow: visible;
  scrollbar-width: none;
}

body.main-shell-host .main-orders-header-filter__dynamic-options::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

body.main-shell-host .main-orders-header-filter__date-range {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 6px;
}

body.main-shell-host .main-orders-header-filter__date-range label {
  display: grid;
  gap: 4px;
  color: #64748b;
  font-size: 10px;
  font-weight: 600;
}

body.main-shell-host .main-orders-header-filter__date-range input[type="date"] {
  width: 100%;
  min-width: 0;
  height: 32px;
  padding: 0 7px;
  border: 1px solid rgba(15, 23, 42, 0.14);
  border-radius: 7px;
  background: #ffffff;
  color: var(--main-text);
  font: inherit;
  font-size: 10px;
  outline: none;
}

body.main-shell-host .main-orders-header-filter__date-range input[type="date"]:focus {
  border-color: var(--main-accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--main-accent) 14%, transparent);
}

body.main-shell-host .main-orders-header-filter__section h4 {
  margin: 0 0 0px;
  color: var(--main-text);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.2;
}

body.main-shell-host .main-orders-header-filter__radio {
  position: relative;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  min-height: 30px;
  color: #475569;
  font-size: 13px;
  font-weight: 400;
  cursor: pointer;
}

body.main-shell-host .main-orders-header-filter__radio input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

body.main-shell-host .main-orders-header-filter__radio-mark {
  display: inline-grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border: 1px solid rgba(15, 23, 42, 0.16);
  border-radius: 999px;
  background: #ffffff;
}

body.main-shell-host
  .main-orders-header-filter__radio
  input:checked
  + .main-orders-header-filter__radio-mark {
  border-color: var(--main-accent);
  background: var(--main-accent);
}

body.main-shell-host
  .main-orders-header-filter__radio
  input:checked
  + .main-orders-header-filter__radio-mark::after {
  content: "";
  width: 10px;
  height: 10px;
  border-radius: inherit;
  background: #ffffff;
}

body.main-shell-host .main-orders-header-filter__radio:focus-within {
  color: var(--main-text);
}

body.main-shell-host .main-orders-header-filter__footer,
body.main-shell-host .main-orders-header-filter__actions {
  flex: 0 0 auto;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  min-height: 50px;
  margin: 0;
  padding: 9px 12px;
  border-top: 1px solid rgba(15, 23, 42, 0.08);
  background: #ffffff;
}

body.main-shell-host .main-orders-header-filter__footer button,
body.main-shell-host .main-orders-header-filter__actions button {
  min-height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: #f2f2f2;
  color: #475569;
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  box-shadow: none;
  cursor: pointer;
}

body.main-shell-host .main-orders-header-filter__footer button:hover,
body.main-shell-host .main-orders-header-filter__footer button:focus-visible,
body.main-shell-host .main-orders-header-filter__actions button:hover,
body.main-shell-host .main-orders-header-filter__actions button:focus-visible {
  background: #e8edf3;
  color: var(--main-text);
  outline: none;
}

@media (max-width: 1100px) {
  body.main-shell-host .main-orders-header-filter__panel {
    right: 0;
    left: auto;
    width: min(540px, calc(100vw - 24px));
